import {it,expect} from 'vitest'
import {fixture} from './fixture'
import {LiveGraph} from './live-graph'
import {returnFixture} from './return-fixture'
class Param{value=.76;calls:any[]=[];setValueAtTime(v:number,t:number){this.calls.push(['set',v,t])}linearRampToValueAtTime(v:number,t:number){this.calls.push(['ramp',v,t])}cancelScheduledValues(t:number){this.calls.push(['cancel',t])}}
class Node{gain=new Param();buffer:any;loop=false;loopStart=0;loopEnd=0;starts:any[]=[];stops:any[]=[];connect(){}disconnect(){}start(...a:any[]){this.starts.push(a)}stop(...a:any[]){this.stops.push(a)}}
function setup(){const nodes:Node[]=[],ctx:any={currentTime:10,createGain(){const n=new Node();nodes.push(n);return n},createBufferSource(){const n=new Node();nodes.push(n);return n}},scene=fixture(),approval:any={scene,entry:{fadeSeconds:.008,sourcePosition:40},nativeGain:.76},buffer:any={duration:80},pcm:any={a:{drums:buffer,bass:buffer,other:buffer},b:{drums:buffer,bass:buffer,other:buffer,vocals:buffer}},original=new Param();return{ctx,approval,pcm,nodes,original}}
it('adds only approved stem layers at the live anchor without replaying A lead or B audition tail',()=>{const f=setup(),g=new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{});expect(f.nodes.filter(n=>n.starts.length)).toHaveLength(7);expect(f.nodes.filter(n=>n.starts.length).every(n=>n.starts[0][0]===20)).toBe(true);expect(f.nodes.filter(n=>n.loop)).toHaveLength(3);expect(f.original.calls).toEqual([['set',.76,20],['ramp',0,20.008]]);expect(g.exit.at).toBe(40)})
it('uses the next approved exit and fades the scene without creating a finite native master',()=>{const f=setup(),g=new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{});f.ctx.currentTime=26;const e=g.nextExit()!;expect(e.at).toBe(20);g.setExit(e);expect(g.end).toBe(40.008);expect(f.nodes.filter(n=>n.starts.length)).toHaveLength(7);expect(g.nextExit()?.at).toBe(20)})
it('does not progress the music clock during pause, and skips a missed fade boundary',()=>{const f=setup(),g=new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{});f.ctx.currentTime=38;expect(g.position).toBe(18);expect(g.position).toBe(18);expect(g.nextExit()?.at).toBe(30)})
it('cancellation before entry restores the existing A deck and stops all created nodes',()=>{const f=setup(),g=new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{});g.cancel();expect(f.original.calls.slice(-2)).toEqual([['cancel',10],['set',.76,10]]);expect(f.nodes.filter(n=>n.starts.length).every(n=>n.stops.length)).toBe(true)})
it('cleans partial graph construction and never schedules A muting when a layer cannot start',()=>{const f=setup(),create=f.ctx.createBufferSource;let count=0;f.ctx.createBufferSource=()=>{const n=create();if(++count===3)n.start=()=>{throw Error('failed source')};return n};expect(()=>new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{})).toThrow('failed source');expect(f.original.calls).toHaveLength(0);expect(f.nodes.filter(n=>n.starts.length).every(n=>n.stops.length)).toBe(true)})
it('preserves the original interpolation before each approved exit fade',()=>{const f=setup();new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{});const a=f.nodes.find(n=>n.gain.calls.some(c=>c[0]==='set'&&c[1]===1&&c[2]===20))!;expect(a.gain.calls).toContainEqual(['ramp',.0625,57.5]);expect(a.gain.calls).not.toContainEqual(['set',.0625,57.5])})
it('uses only measured return exits and schedules their intermediate knots exactly',()=>{
 const f=setup();f.approval=returnFixture();const e=f.approval.evidence.returnToA.exits.at(-1),a=e.layers.find((l:any)=>l.side==='a'&&l.role==='bass'),b=e.layers.find((l:any)=>l.side==='b'&&l.role==='bass');a.points.splice(-1,0,[28,0.3125],[29,1]);b.points.splice(-1,0,[28,0]);
 const g=new LiveGraph(f.ctx,new Node() as any,f.approval,f.pcm,f.original as any,20,()=>{});expect(g.exit.at).toBe(30);expect(g.end).toBe(50.008)
 const n=f.nodes.filter(n=>n.gain.calls.some(c=>c[0]==='ramp'&&c[1]===1&&c[2]===49));expect(n).toHaveLength(1)
 expect(n[0].gain.calls).toContainEqual(['ramp',.3125,48]);expect(n[0].gain.calls).toContainEqual(['ramp',1,50])
 f.ctx.currentTime=26;g.setExit(f.approval.scene.exits[0]);expect(g.end).toBe(40.008)
})
